function tp(string $h,int $port,string $db,string $u,string $pw):PDO{return new PDO("mysql:host=$h;port=$port;dbname=$db;charset=utf8mb4",$u,$pw,[PDO::ATTR_ERRMODE=>PDO::ERRMODE_EXCEPTION]);}
function base(PDO $p):void{$p->exec("CREATE TABLE bank_transactions(id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,account_id INT UNSIGNED NOT NULL DEFAULT 1,operation_date DATE NOT NULL,document_number VARCHAR(100),operation_type VARCHAR(30),counterparty_name VARCHAR(255),counterparty_inn VARCHAR(20),debit_amount DECIMAL(15,2) NOT NULL DEFAULT 0,credit_amount DECIMAL(15,2) NOT NULL DEFAULT 0,purpose TEXT,classification_status VARCHAR(30) NOT NULL DEFAULT 'UNALLOCATED',is_internal_transfer TINYINT(1) NOT NULL DEFAULT 0) ENGINE=InnoDB");$p->exec("CREATE TABLE finance_employee_movements(id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,bank_transaction_id INT UNSIGNED NULL) ENGINE=InnoDB");$p->exec("CREATE TABLE documents(id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,entity_type VARCHAR(20) NOT NULL,entity_id INT UNSIGNED NOT NULL,document_type VARCHAR(100),document_type_id INT UNSIGNED NULL,original_name VARCHAR(500) NOT NULL,stored_name VARCHAR(255) NOT NULL,relative_path VARCHAR(1000) NOT NULL,mime_type VARCHAR(100) NOT NULL,file_size BIGINT UNSIGNED NOT NULL,status VARCHAR(20) NOT NULL DEFAULT 'uploaded',deleted_at DATETIME NULL,created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP) ENGINE=InnoDB");$p->exec("CREATE TABLE document_types(id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,name VARCHAR(255),code VARCHAR(100)) ENGINE=InnoDB");foreach(['077_finance_closing_documents.sql','078_finance_closing_document_exceptions.sql','079_finance_closing_document_exception_purpose.sql'] as $m){$sql=file_get_contents(__DIR__.'/../database/migrations-local/'.$m);if($sql===false)throw new RuntimeException('missing '.$m);$p->exec($sql);}a(ClosingDocumentService::schemaReady($p),'schema ready');}
function tx(PDO $p,string $name,string $inn,string $purpose='test',bool $incoming=false,bool $internal=false):int{$s=$p->prepare("INSERT INTO bank_transactions(operation_date,document_number,operation_type,counterparty_name,counterparty_inn,debit_amount,credit_amount,purpose,is_internal_transfer) VALUES(CURDATE(),?,'PAYMENT',?,?,?,?,?,?)");$s->execute([uniqid('t'),$name,$inn,$incoming?0:1000,$incoming?1000:0,$purpose,$internal?1:0]);return(int)$p->lastInsertId();}
function addDoc(PDO $p,int $tx,string $code):int{$s=$p->prepare("INSERT INTO documents(entity_type,entity_id,document_type,original_name,stored_name,relative_path,mime_type,file_size,status) VALUES('bank_transaction',?,?,?,?,?,'application/pdf',100,'uploaded')");$s->execute([$tx,$code,$code.'.pdf',uniqid('d').'.pdf','test/'.$code.'.pdf']);$id=(int)$p->lastInsertId();$l=$p->prepare('INSERT INTO finance_closing_document_links(bank_transaction_id,document_id,requirement_code) VALUES(?,?,?)');$l->execute([$tx,$id,$code]);return$id;}
function done(PDO $p,int $tx,string $profile):void{addDoc($p,$tx,'agreement');addDoc($p,$tx,'act');if($profile==='self_employed')addDoc($p,$tx,'npd_receipt');}
$A=tp($h,$port,$dba,$u,$pw);$B=tp($h,$port,$dbb,$u,$pw);base($A);base($B);
