$r1=tx($A,'ООО Ромашка','7700000001');$shared=addDoc($A,$r1,'agreement');$r2=tx($A,'ООО Ромашка','7700000001');ClosingDocumentService::linkExistingDocument($A,$r2,$shared,'agreement',1);$q=$A->prepare('SELECT COUNT(DISTINCT bank_transaction_id) FROM finance_closing_document_links WHERE document_id=?');$q->execute([$shared]);eq(2,(int)$q->fetchColumn(),'same-INN reuse');$other=tx($A,'ООО Другой','7700000010');$blocked=false;try{ClosingDocumentService::linkExistingDocument($A,$other,$shared,'agreement',1);}catch(RuntimeException){$blocked=true;}a($blocked,'cross-INN reuse blocked');
